  if (threadIdx.x == 0) {
    const float pre_s = scale[0], post_s = scale[1], comb_s = scale[2];
    for (int i = 0; i < hc; ++i) pre[i] = sigmoidf(mx_row[i] * pre_s + base[i]) + hc_eps;
    for (int i = 0; i < hc; ++i)
      post_row[i] = 2.0f * sigmoidf(mx_row[hc + i] * post_s + base[hc + i]);
    for (int r = 0; r < hc; ++r) {
      float mxv = -CUDART_INF_F;
      for (int c = 0; c < hc; ++c) {
