  ck(cudaStreamWaitEvent(z.selector_stream,z.selector_ready,0),"selector stream wait");
  gemm_bf16_cublas(z.selector_hidden,
                    static_cast<const bf16*>(z.w.tensor_data("candidate_selector.hidden_projection.weight")),
