    for (int& id : local_ids) id += vocab_begin;
    z.ep->exchange_draft_candidates(local_ids,local_vals,peer_ids,peer_vals);
    std::vector<int> merged_ids(count);
    std::vector<float> merged_vals(count);
    for (int r=0;r<sample_rows;++r) {
