  std::fprintf(stderr,"[dflash2-profile] layers=%.3f ms candidates=%.3f ms selector=%.3f ms\n",
               layers,candidates,selector);
  cudaEventDestroy(ev0); cudaEventDestroy(ev1); cudaEventDestroy(ev2); cudaEventDestroy(ev3);
#endif
}

