  const int vocab_begin = z.ep ? z.ep->rank() * (z.w.cfg.vocab_size / 2) : 0;
  const int local_vocab = z.ep ? (z.ep->rank() == 0 ? z.w.cfg.vocab_size / 2
                                                   : z.w.cfg.vocab_size - vocab_begin)
                               : z.w.cfg.vocab_size;
