int NvmePrefixStore::open_segment(std::uint32_t segment, bool create) {
  const auto path = segment_path(options_.directory, segment);
  const int flags = O_RDWR | O_DIRECT | O_CLOEXEC | O_NOFOLLOW | (create ? O_CREAT : 0);
